	@Test
	void onlyTheScheduledExpiryPublishesExpirationNeverAClockRead() {
		AtomicReference<Runnable> scheduledExpiry = new AtomicReference<>();
		QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1L, (expiry, deadlineMillis) -> {
			scheduledExpiry.set(expiry);
			return () -> {
			};
		});
		try {
			CompletableFuture<Void> listener = new CompletableFuture<>();
			deadline.onExpiration(() -> listener.complete(null));
			// The premise is wall-clock time passing, not synchronization: wait until the deadline is in the past.
			while (System.currentTimeMillis() <= deadline.deadlineMillis()) {
				Thread.onSpinWait();
			}
			assertFalse(deadline.isExpired(),
					"inner checks must not track time; only the deadline's scheduled expiry may expire it");
			assertFalse(listener.isDone(), "no reader may publish expiration before the scheduled expiry runs");

			scheduledExpiry.get().run();
			assertTrue(deadline.isExpired(), "the scheduled expiry publishes expiration before it returns");
			// Listeners may run off the timer thread; await them causally rather than polling.
			assertDoesNotThrow(() -> listener.get(10, TimeUnit.SECONDS), "the scheduled expiry runs listeners");
		} finally {
			deadline.close();
		}
	}

